(() => {
 const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const extra=document.createElement('fieldset');extra.className='product-extra';extra.innerHTML=`<legend>Detalhes do produto</legend><div class="form-grid"><label>Capacidade<input id="detail-capacity" maxlength="80" placeholder="Ex.: 128 GB"></label><label>Cor<input id="detail-color" maxlength="80" placeholder="Ex.: Preto"></label><label>Saúde da bateria (%)<input id="detail-battery" type="number" min="0" max="100" step="1" placeholder="Opcional, para seminovos"></label><label class="full">Garantia deste produto<textarea id="detail-warranty" maxlength="1000" rows="2" placeholder="Informe prazo e condições reais"></textarea></label><label class="full">Ficha técnica e itens inclusos<textarea id="detail-specs" maxlength="3000" rows="4"></textarea></label><label class="full">Fotos adicionais (até 5)<textarea id="detail-gallery" rows="3" placeholder="Um link HTTPS por linha"></textarea></label></div><h3>Opções de cor e capacidade</h3><p class="helper">Se houver opções, o preço e o estoque da vitrine serão calculados a partir delas. Para seminovos com baterias ou condições diferentes, cadastre produtos separados.</p><div id="variant-rows"></div><button type="button" class="secondary" id="add-variant">+ Adicionar opção</button>`;
 $('#product-form .switches').before(extra);
 const addVariant=(v={})=>{if($('#variant-rows').children.length>=20)return;const row=document.createElement('div');row.className='variant-row';row.innerHTML=`<label>Cor<input data-v="color" maxlength="80" value="${esc(v.color)}"></label><label>Capacidade<input data-v="capacity" maxlength="80" value="${esc(v.capacity)}"></label><label>Preço (R$)<input data-v="price" type="number" min="0" max="1000000" step="0.01" placeholder="Sob consulta" value="${v.price==null?'':v.price/100}"></label><label>Estoque<input data-v="stock" type="number" min="0" max="1000000" step="1" value="${v.stock??0}" required></label><button type="button" class="secondary" aria-label="Remover opção">Remover</button>`;row.querySelector('button').onclick=()=>{row.remove();variantState();};$('#variant-rows').append(row);variantState();};
 function variantState(){const has=$('#variant-rows').children.length>0;for(const name of ['price','stock']){$('#product-form').elements[name].readOnly=has;$('#product-form').elements[name].title=has?'Calculado pelas opções abaixo':'';}}
 $('#add-variant').onclick=()=>addVariant();
 window.populateProductDetails=p=>{const d=p?.details||{};for(const k of ['capacity','color','battery','warranty','specs'])$('#detail-'+k).value=d[k]??'';$('#detail-gallery').value=(d.gallery||[]).join('\n');$('#variant-rows').replaceChildren();(d.variants||[]).forEach(addVariant);variantState();};
 window.readProductDetails=()=>({capacity:$('#detail-capacity').value,color:$('#detail-color').value,battery:$('#detail-battery').value===''?null:Number($('#detail-battery').value),warranty:$('#detail-warranty').value,specs:$('#detail-specs').value,gallery:$('#detail-gallery').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),variants:[...$('#variant-rows').children].map(row=>({color:row.querySelector('[data-v=color]').value,capacity:row.querySelector('[data-v=capacity]').value,price:row.querySelector('[data-v=price]').value===''?null:Math.round(Number(row.querySelector('[data-v=price]').value)*100),stock:Number(row.querySelector('[data-v=stock]').value)}))});
 const nav=document.createElement('button');nav.className='nav-item';nav.dataset.view='reviews';nav.innerHTML='◇ <span>Avaliações</span>';$('.sidebar nav').append(nav);
 const section=document.createElement('section');section.id='view-reviews';section.hidden=true;
 section.innerHTML='<div class="page-heading"><div><p class="eyebrow">VOZ DOS CLIENTES</p><h1>Avaliações</h1><p>Publique depoimentos reais com autorização do cliente.</p></div></div><form id="reviews-form" class="appearance-card"><fieldset id="reviews-fields" disabled><p class="helper">A seção aparece no site depois de salvar a primeira avaliação. Você pode publicar até dez depoimentos.</p><div id="review-rows"></div><button type="button" id="add-review" class="secondary">+ Adicionar avaliação</button><p id="reviews-status" role="status"></p><button class="primary" id="save-reviews">Salvar avaliações</button></fieldset></form><p id="reviews-load-error" role="alert"></p><button class="secondary" id="reload-reviews" type="button">Atualizar avaliações</button>';$('.page').append(section);
 let version=0;
 const addReview=(r={})=>{if($('#review-rows').children.length>=10)return;const row=document.createElement('div');row.className='review-editor';row.innerHTML='<label>Nome do cliente<input data-r="name" maxlength="80" required></label><label>Avaliação<textarea data-r="text" maxlength="1000" rows="3" required></textarea></label><label class="review-consent"><input type="checkbox" data-r="approved" required> Confirmo que esta avaliação é real e sua publicação está autorizada.</label><button type="button" class="secondary">Remover avaliação</button>';row.querySelector('[data-r=name]').value=r.name||'';row.querySelector('[data-r=text]').value=r.text||'';row.querySelector('[data-r=approved]').checked=r.approved===true;row.querySelector('button').onclick=()=>row.remove();$('#review-rows').append(row);};
 $('#add-review').onclick=()=>addReview();
 async function request(options){const r=await fetch('/api/admin/reviews',options),b=await r.json();if(!r.ok)throw Error(b.error||'Não foi possível carregar.');return b;}
 window.loadReviews=async()=>{$('#reviews-load-error').textContent='';$('#reviews-fields').disabled=true;try{const data=await request();version=data.version;$('#review-rows').replaceChildren();(data.content.reviews||[]).forEach(addReview);$('#reviews-fields').disabled=false;}catch(e){$('#reviews-load-error').textContent=e.message;}};
 $('#reload-reviews').onclick=window.loadReviews;
 $('#reviews-form').onsubmit=async e=>{e.preventDefault();const content={reviews:[...$('#review-rows').children].map(r=>({name:r.querySelector('[data-r=name]').value,text:r.querySelector('[data-r=text]').value,approved:r.querySelector('[data-r=approved]').checked}))};$('#save-reviews').disabled=true;try{const data=await request({method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({content,version})});version=data.version;$('#reviews-status').textContent='Avaliações salvas na vitrine.';}catch(err){$('#reviews-status').textContent=err.message;}finally{$('#save-reviews').disabled=false;}};
})();
